import { DueCardsView } from '../DueCards';
import { OperationalFiltersCard } from '../shared/OperationalFiltersCard';
import { DiligenceFilterView } from './DiligenceFilterView';
import { DueDiligenceStatisticsView } from './Views/DueDiligenceStatisticsView';

export function DueDiligenceScreenView() {
    return (
        <>
            <div className="col-span-full">
                <DueDiligenceStatisticsView />
            </div>

            <OperationalFiltersCard>
                <DiligenceFilterView />
            </OperationalFiltersCard>

            <div className="col-span-full">
                <DueCardsView />
            </div>
        </>
    );
}

