'use client';

import { ActiveViewType } from '../enums';
import { useDueDiligenceActiveView } from '../hooks/use-due-diligence-active-view';
import { ArquivamentosScreen } from '../Views/ArquivamentosScreen';
import { DueDiligenceScreenView } from '../Views/DueDiligenceScreen';
import { PendenciasScreen } from '../Views/PendenciasScreen';
import { RepactuacoesScreenView } from '../Views/RepactuacoesScreen';
import { LiquidacaoScreenView } from '../Views/LiquidacaoScreen';
import { RevisaoArquivamentoScreen } from '../Views/RevisaoArquivamentoScreen';

function renderActiveView(currentView: ActiveViewType) {
    switch (currentView) {
        case ActiveViewType.DUE_DILIGENCE:
            return <DueDiligenceScreenView />;
        case ActiveViewType.PENDENCIAS:
            return <PendenciasScreen />;
        case ActiveViewType.REPACTUACOES:
            return <RepactuacoesScreenView />;
        case ActiveViewType.LIQUIDACAO:
            return <LiquidacaoScreenView />;
        case ActiveViewType.ARQUIVADOS:
            return <ArquivamentosScreen />;
        case ActiveViewType.REVISAO_ARQUIVAMENTO:
            return <RevisaoArquivamentoScreen />;
        default:
            return null;
    }
}

export function DueDiligenceContainer() {
    const { activeView } = useDueDiligenceActiveView();

    return renderActiveView(activeView);
}

