'use client';

import { DueDiligenceContainer } from './Container';
import { DueDiligenceActiveViewProvider } from './hooks/use-due-diligence-active-view';
import { ActiveTabsView } from './Views/ActiveViewTabs';
import { DashboardOpsButton } from './Views/ActiveViewTabs/DashboardOpsButton';
import { DueCardsSharedModalsView } from './Views/DueCardsSharedModalsView';
import { ObservationsSheetView } from './Views/ObservationsSheetView';

export function DueDiligenceShell() {
    return (
        <div className="grid min-w-0 grid-cols-12 gap-y-4 bg-celer-panel px-3 pb-6 pt-4 sm:px-5 md:gap-y-5 md:px-8 md:pb-8 md:pt-6">
            <DueDiligenceActiveViewProvider>
                <header className="col-span-full">
                    <ActiveTabsView dashboardOps={<DashboardOpsButton />} />
                </header>

                <DueDiligenceContainer />
            </DueDiligenceActiveViewProvider>
            <ObservationsSheetView />
            <DueCardsSharedModalsView />
        </div>
    );
}

