'use client';

import { useMemo } from 'react';
import { useOperationalListFilterQueryState } from '../../../hooks/useOperationalListFilterQueryState';
import { DueActiveViewTabsService } from '../../../services/ActiveViewTabs';
import { useViewModelDiligenceFilter } from '../../../ViewModels/useViewModelDiligenceFilter';
import { OperationalFilterGridView } from '../../shared/OperationalFilterGridView';
import { OperationalListExportActions } from '../../shared/OperationalListExportActions';
import { LiquidacaoViewModeSwitcher } from './LiquidacaoViewModeSwitcher';

export function LiquidacaoFilterView() {
    const service = useMemo(() => new DueActiveViewTabsService(), []);
    const viewModel = useViewModelDiligenceFilter(service);
    const { viewMode, setViewMode } = useOperationalListFilterQueryState();
    const isCrmView = viewMode === 'crm';

    return (
        <OperationalFilterGridView
            fields={viewModel.fieldHandlers}
            disabled={isCrmView}
            headerActions={
                <div className="flex min-w-0 flex-wrap items-center justify-end gap-2">
                    <LiquidacaoViewModeSwitcher
                        viewMode={viewMode}
                        onViewModeChange={setViewMode}
                    />
                    <OperationalListExportActions dueProcess="liquidation" />
                </div>
            }
        />
    );
}

